// Regenerates grammar-data.js from tools/bunpro-grammar.json, the output of
// tools/bunpro-structure.js. Run by hand; the app has no build step and ships
// the generated file as committed source.
//
//   node tools/build-grammar-data.mjs            # reads tools/bunpro-grammar.json
//   node tools/build-grammar-data.mjs some.json  # a path from where you ran it
//
// The input is a list of names and levels. build() asserts rather than warns:
// it refuses anything that is not that shape, so a file that grew a field it
// should not have stops the build. That refusal is the point, and it is what
// the tests pin.
import {readFileSync, writeFileSync} from "node:fs";
import {resolve} from "node:path";
import {pathToFileURL} from "node:url";

export const LEVELS = ["N5", "N4", "N3", "N2", "N1"];
const ALLOWED = new Set(["slug", "title", "level", "order", "hint"]);

// A slug read off the page is URL-encoded ("%E3%81%A0" for だ). The id is the
// readable form: the model is asked to answer with ids, and it can copy だ
// where it would mangle a hex string.
export function idFromSlug(slug) { try { return decodeURIComponent(slug); } catch { return slug; } }

export function build(raw) {
  if (!Array.isArray(raw) || !raw.length) throw new Error("the grammar list is not a non-empty array");
  const seen = new Set(), points = [];
  for (const [i, p] of raw.entries()) {
    const extra = Object.keys(p).filter(k => !ALLOWED.has(k));
    if (extra.length) throw new Error(`entry ${i} carries fields this list must not: ${extra.join(", ")}`);
    if (!p.slug || !p.title) throw new Error(`entry ${i} has no slug or title`);
    if (!LEVELS.includes(p.level)) throw new Error(`entry ${i} (${p.slug}) has level ${JSON.stringify(p.level)}, expected one of ${LEVELS.join(" ")}`);
    if (typeof p.title !== "string" || p.title.length > 80) throw new Error(`entry ${i} title is not a short string`);
    if (p.hint && (typeof p.hint !== "string" || p.hint.length > 80)) throw new Error(`entry ${i} hint is not a short string`);
    if (p.order !== undefined && !Number.isInteger(p.order)) throw new Error(`entry ${i} order is not an integer`);
    const id = idFromSlug(p.slug);
    if (seen.has(id)) continue;
    seen.add(id);
    points.push({id, title: p.title.trim(), level: p.level, order: Number.isInteger(p.order) ? p.order : i, hint: (p.hint || "").trim()});
  }
  const byLevel = Object.fromEntries(LEVELS.map(l => [l, points.filter(p => p.level === l).length]));
  for (const l of LEVELS) if (!byLevel[l]) throw new Error(`no ${l} points at all — the extractor probably missed a heading`);
  // Level order first; within a level, the order the index listed them in.
  points.sort((a, b) => LEVELS.indexOf(a.level) - LEVELS.indexOf(b.level) || a.order - b.order);
  return {points, byLevel};
}

export function render(points) {
  return `// Generated by tools/build-grammar-data.mjs — do not edit by hand.
//
// Grammar points by JLPT level: a name, a level, and where the index showed
// one, a short gloss, and the position each held on the index — the teaching
// order. Nothing more — no explanations, no example sentences,
// no audio. The list was read off the index of the user's own Bunpro account
// by tools/bunpro-structure.js; which points exist and where they sit is the
// table of contents, and Echo writes its own sentences and stories on top.

export const LEVELS = ${JSON.stringify(LEVELS)};

export const GRAMMAR = [
${points.map(p => "  " + JSON.stringify(p) + ",").join("\n")}
];
`;
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const src = process.argv[2] ? resolve(process.argv[2]) : new URL("./bunpro-grammar.json", import.meta.url);
  const {points, byLevel} = build(JSON.parse(readFileSync(src, "utf8")));
  writeFileSync(new URL("../grammar-data.js", import.meta.url), render(points));
  console.log(`grammar-data.js: ${points.length} points`, byLevel);
}
